        self.force_single_line = force_single_line
        self.single_line_exclusions = single_line_exclusions or []
        self.only_sections = only_sections
        self.reverse_sort = reverse_sort
        self.combine_as_imports = combine_as_imports
        self.combine_star = combine_star
        self.line_length = line_length
        self.split_on_trailing_comma = split_on_trailing_comma
        self.multi_line_output = multi_line_output

class MockParsedContent:
    def __init__(self):
        self.imports = {'imports': {'from': {}}}
        self.categorized_comments = {'from': {}, 'above': {}, 'nested': {}, 'straight': {}}
        self.as_map = {'from': {}}
        self.line_separator = '\n'


@pytest.fixture
def mock_config():
    return MockConfig()

@pytest.fixture
def mock_parsed_content():
    return MockParsedContent()


