    mock_parsed_content.imports['imports']['from'] = {
        'module1': ['func1', 'func2'],
        'module2': ['func3', 'func4']
    }
    from_modules = ['module1', 'module2']
    remove_imports = []
    result = _with_from_imports(mock_parsed_content, mock_config, from_modules, 'imports', remove_imports, '')
    assert result == [
        'from module1 func1',
        'from module1 func2',
